// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;

    function setUp() public {
        c = new LiquidityPool(0, bytes16(0), address(this), address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address actor, address from, address to, uint256 amount, bool underlyingReturn) public {
        vm.assume(actor != address(c));
        vm.assume(from != address(c));
        vm.assume(to != address(c));

        __InvMutHandleStub share = __InvMutHandleStub(payable(address(c.share())));
        share.setTransferFromReturn(underlyingReturn);

        vm.prank(actor);
        bool returned = c.transferFrom(from, to, amount);

        assertTrue(returned == share.lastTransferFromReturn(), "transferFrom must return the share token's return value");
    }
}

contract __InvMutHandleStub {
    bool public transferFromReturn;
    bool public lastTransferFromReturn;

    function setTransferFromReturn(bool r) external { transferFromReturn = r; }

    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external returns (bool) {
        lastTransferFromReturn = transferFromReturn;
        return transferFromReturn;
    }
    function checkTransferRestriction(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
